"""Observe actual JavaScript node identity and readonly query contracts."""
from harness_random04 import uniform_parts
CORE=r'''
function nodeCheck4(ok,message){if(!ok)throw Error(message);}
function nodeSnapshot4(actor){
 const root=actor.Root,pending=root===null?[]:[root],nodes=[],links=[],seen=new Set();
 while(pending.length){const node=pending.pop();nodeCheck4(node instanceof RandomNode,'Use provided RandomNode');nodeCheck4(!seen.has(node)&&nodes.length<1000,'Root must be a finite proper tree');nodeCheck4(Number.isInteger(node.Data)&&node.Data>=-2147483648&&node.Data<=2147483647,'Preserve signed integer Data');seen.add(node);nodes.push(node);links.push([node.Data,node.Left,node.Right]);if(node.Right!==null)pending.push(node.Right);if(node.Left!==null)pending.push(node.Left);}
 const ordered=[],stack=[];let node=root;while(node!==null||stack.length){while(node!==null){stack.push(node);node=node.Left;}node=stack.pop();ordered.push(node);node=node.Right;}
 const values=ordered.map(node=>node.Data);nodeCheck4(values.every((v,i)=>i===0||values[i-1]<=v),'Maintain BST inorder');return {root,nodes,links,ordered,values,rank:new Map(ordered.map((node,i)=>[node,i]))};
}
function nodeQuery4(actor,before,node){nodeCheck4(actor.Root===before.root&&before.nodes.every((old,i)=>old.Data===before.links[i][0]&&old.Left===before.links[i][1]&&old.Right===before.links[i][2]),'Queries preserve Data and links');nodeCheck4(node===null||node instanceof RandomNode&&before.rank.has(node),'Return actual current node');return node===null?[]:[node.Data];}
function nodeBasic4(actor,operation,args){if(operation==='Insert'){nodeCheck4(actor.Insert(args[0])===undefined,'Insert returns undefined');return null;}if(operation==='Delete'){const result=actor.Delete(args[0]);nodeCheck4(typeof result==='boolean','Delete returns boolean');return result;}const before=nodeSnapshot4(actor);if(operation==='Find')return nodeQuery4(actor,before,actor.Find(args[0]));if(operation==='GetRandomNode')return nodeQuery4(actor,before,actor.GetRandomNode());throw Error('Unknown operation');}
function nodeDelta4(before,after){let i=0,j=0;const added=[],removed=[];while(i<before.length&&j<after.length){if(before[i]===after[j]){++i;++j;}else if(before[i]<after[j])removed.push(before[i++]);else added.push(after[j++]);}removed.push(...before.slice(i));added.push(...after.slice(j));return {added,removed,count:after.length};}
const NodeContext4={operations:[],arguments:[],values:[],build(){const actor=new RandomBst();for(let i=1;i<this.operations.length;++i)nodeBasic4(actor,this.operations[i],this.arguments[i]);return actor;}};
class NodeShuffle4{constructor(){this.actor=null;}Shuffle(array){if(this.actor===null)this.actor=NodeContext4.build();const before=nodeSnapshot4(this.actor);nodeCheck4(JSON.stringify(before.values)===JSON.stringify(NodeContext4.values)&&array.length===before.values.length,'Preserve operation-prefix multiset');const chosen=this.actor.GetRandomNode();nodeQuery4(this.actor,before,chosen);if(!array.length){nodeCheck4(chosen===null,'Empty query returns null');return;}nodeCheck4(chosen!==null,'Nonempty query returns current node');const selected=before.rank.get(chosen),remaining=Array.from({length:array.length},(_,i)=>i).filter(i=>i!==selected);for(let i=remaining.length-1;i>0;--i){const other=RandomSource.GetRandom(0,i);[remaining[i],remaining[other]]=[remaining[other],remaining[i]];}array.splice(0,array.length,selected,...remaining);}}
'''
ENDING=r'''
function executeRandomBst4(row){const [operations,args]=row.arguments;let seed=0x411b57;const liveDraw=(lower,upper)=>{nodeCheck4(Number.isInteger(lower)&&Number.isInteger(upper)&&0<=lower&&lower<=upper&&upper<=2147483647,'Use valid inclusive integer bounds');seed=(Math.imul(seed,1664525)+1013904223)>>>0;return lower+Number((BigInt(seed)*BigInt(upper-lower+1))>>32n);};RandomSource.Draw=liveDraw;const actor=new RandomBst();let before=nodeSnapshot4(actor);const results=[null],changes=[nodeDelta4([],before.values)];for(let i=1;i<operations.length;++i){if(operations[i]==='GetRandomNode'){NodeContext4.operations=operations.slice(0,i);NodeContext4.arguments=args.slice(0,i);NodeContext4.values=before.values.slice();const saved=RandomSource.Draw;try{executeRandom4_11({arguments:[before.values.map((_,i)=>i)]});}finally{RandomSource.Draw=saved;}nodeCheck4(actor.Root===before.root,'Instances own independent tree state');}results.push(nodeBasic4(actor,operations[i],args[i]));const after=nodeSnapshot4(actor);changes.push(nodeDelta4(before.values,after.values));before=after;}return {actual:{results,finalValues:before.values},changes,mutationOk:true,uniformOk:true};}
'''
def parts(code):
    outside,inside=uniform_parts('javascript',code+CORE)
    return outside+ENDING,inside
